@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row justify-content-center mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <p class="text-center"><em>Searching...</em></p>
}
else if (notFound)
{
    <div class="alert alert-warning text-center">
        No shipment found with tracking number <strong>@searchedNumber</strong>.
    </div>
}
else if (shipment is not null)
{
    <div class="card mx-auto" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-5">Origin</dt>
                <dd class="col-sm-7">@shipment.Origin</dd>

                <dt class="col-sm-5">Destination</dt>
                <dd class="col-sm-7">@shipment.Destination</dd>

                <dt class="col-sm-5">Recipient</dt>
                <dd class="col-sm-7">@shipment.RecipientName</dd>

                <dt class="col-sm-5">Shipped Date</dt>
                <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                <dt class="col-sm-5">Estimated Delivery</dt>
                <dd class="col-sm-7">
                    <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                    @if (shipment.Status != ShipmentStatus.Delivered)
                    {
                        var daysLeft = (shipment.EstimatedDelivery - DateTime.Today).Days;
                        <br />
                        <small class="text-muted">
                            @if (daysLeft > 0)
                            {
                                @($"({daysLeft} day{(daysLeft == 1 ? "" : "s")} remaining)")
                            }
                            else if (daysLeft == 0)
                            {
                                @("(Expected today)")
                            }
                            else
                            {
                                @($"(Overdue by {-daysLeft} day{(-daysLeft == 1 ? "" : "s")})")
                            }
                        </small>
                    }
                </dd>

                @if (!string.IsNullOrWhiteSpace(shipment.Notes))
                {
                    <dt class="col-sm-5">Notes</dt>
                    <dd class="col-sm-7">@shipment.Notes</dd>
                }
            </dl>
        </div>
    </div>
}

